def semver_sort(versions):
    def parse(v):
        # split build metadata
        main = v.split('+', 1)[0]
        if '-' in main:
            core, prerelease = main.split('-', 1)
        else:
            core, prerelease = main, None
        major, minor, patch = (int(x) for x in core.split('.'))
        if prerelease is None:
            has_pre = 1  # no prerelease sorts after
            pre_key = ()
        else:
            has_pre = 0
            ids = prerelease.split('.')
            pre_key = tuple((0, int(i)) if i.isdigit() else (1, i) for i in ids)
        return (major, minor, patch, has_pre, pre_key)

    indexed = list(enumerate(versions))
    indexed.sort(key=lambda pair: (parse(pair[1]), pair[0]))
    return [v for _, v in indexed]

